{"path":"pricing.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8" />
  <meta name="viewport" content="width=device-width,initial-scale=1" />
  <title>Membership Plans — {{BUSINESS_NAME}}</title>
  <style>
    :root{--bg:#fbfaf8;--muted:#6b6b6b;--accent:#6b9f78;--deep:#2f4a3e;--glass:rgba(255,255,255,0.6);--card:#ffffff}
    html,body{height:100%;margin:0;font-family:system-ui,-apple-system,Segoe UI,Roboto,Helvetica,Arial;line-height:1.45;color:var(--deep);background:linear-gradient(180deg,var(--bg),#f3f6f2);}
    header{background:linear-gradient(90deg,rgba(107,159,120,0.06),rgba(47,74,62,0.02));backdrop-filter:blur(4px);padding:20px 24px;position:sticky;top:0;z-index:40;border-bottom:1px solid rgba(47,74,62,0.04)}
    .wrap{max-width:1100px;margin:0 auto}
    .nav{display:flex;gap:18px;align-items:center;justify-content:space-between}
    .brand{font-weight:700;color:var(--deep)}
    .navlinks{display:flex;gap:12px;align-items:center}
    .navlinks a{color:var(--deep);text-decoration:none;padding:8px 10px;border-radius:8px;font-size:15px}
    .navlinks a:hover{background:rgba(47,74,62,0.06)}
    .primary-cta{background:var(--accent);color:white;padding:8px 12px;border-radius:8px;text-decoration:none}

    main{padding:36px 20px}
    .hero{display:grid;grid-template-columns:1fr;gap:18px;align-items:center;margin-bottom:20px}
    .hero .lead{background:var(--card);padding:24px;border-radius:12px;box-shadow:0 6px 18px rgba(46,60,50,0.06);}
    .kicker{font-size:13px;color:var(--muted);text-transform:uppercase;letter-spacing:1px}
    h1{margin:8px 0 4px;font-size:28px}
    p.lead-p{margin:0;color:var(--muted)}

    .plans{display:grid;grid-template-columns:repeat(auto-fit,minmax(240px,1fr));gap:16px;margin-top:18px}
    .plan{background:linear-gradient(180deg,rgba(255,255,255,0.9),var(--card));padding:18px;border-radius:12px;border:1px solid rgba(47,74,62,0.04);box-shadow:0 8px 20px rgba(45,55,45,0.04)}
    .plan h3{margin:0 0 6px}
    .price{font-weight:700;font-size:20px;color:var(--deep)}
    .badge{display:inline-block;background:rgba(107,159,120,0.12);color:var(--deep);padding:6px 8px;border-radius:999px;font-size:13px;margin-top:8px}
    .features{margin:12px 0;color:var(--muted);font-size:14px}
    .plan a{display:inline-block;margin-top:10px;padding:8px 12px;background:var(--accent);color:white;border-radius:8px;text-decoration:none}

    .faq{margin-top:26px;padding:18px;background:linear-gradient(180deg,#fff,rgba(255,255,255,0.95));border-radius:12px}
    .faq h4{margin:0 0 10px}
    .faq p{margin:6px 0;color:var(--muted)}

    footer{padding:26px 20px;margin-top:36px;text-align:center;color:var(--muted);font-size:14px}

    /* try-it modal */
    .modal-backdrop{position:fixed;inset:0;background:rgba(12,12,10,0.4);display:flex;align-items:center;justify-content:center;z-index:120;}
    .modal{background:var(--card);width:min(680px,96vw);border-radius:12px;padding:20px;box-shadow:0 20px 60px rgba(18,30,20,0.35)}
    .modal h3{margin:0 0 8px}
    .controls{display:flex;gap:8px;align-items:center;margin-top:12px}
    .btn{padding:8px 12px;border-radius:8px;border:none;background:var(--accent);color:white}
    .ghost{background:transparent;border:1px solid rgba(47,74,62,0.08);color:var(--deep)}
    .step{padding:12px;background:rgba(245,247,244,0.8);border-radius:10px;margin-top:10px}

    /* reveal */
    .reveal{opacity:0;transform:translateY(18px);transition:opacity 520ms cubic-bezier(.2,.9,.2,1),transform 520ms cubic-bezier(.2,.9,.2,1)}
    .reveal.visible{opacity:1;transform:none}
    @media (prefers-reduced-motion:reduce){.reveal{transition:none;transform:none;opacity:1}}

    /* small */
    @media(min-width:760px){.hero{grid-template-columns:1fr 380px}}
  </style>
</head>
<body>
  <header>
    <div class="wrap nav">
      <div class="brand">{{BUSINESS_NAME}}</div>
      <nav class="navlinks" aria-label="Main navigation">
        <a href="index.html">Welcome</a>
        <a href="services.html">Offerings</a>
        <a href="blends.html">Blends</a>
        <a href="shop.html">Shop</a>
        <a href="pricing.html">Membership</a>
        <a href="about.html">Our Path</a>
        <a href="book.html">Reserve</a>
        <a class="primary-cta" href="contact.html">Reach</a>
      </nav>
    </div>
  </header>

  <main class="wrap">
    <section class="hero">
      <div class="lead reveal" data-reveal>
        <div class="kicker">Membership</div>
        <h1>Careful scent practice, steady habit</h1>
        <p class="lead-p">A membership that blends simple at-home rituals, guided sessions, and safe blending guidance to help you build a scent-attuned routine that may support daily balance.</p>
        <div style="margin-top:12px">
          <button class="btn" id="open-try">Try it now — short practice</button>
          <a href="#plans" style="margin-left:10px;color:var(--muted);text-decoration:none">See tiers</a>
        </div>
      </div>
      <aside class="reveal" data-reveal>
        <div style="background:linear-gradient(180deg,rgba(107,159,120,0.06),rgba(47,74,62,0.02));padding:18px;border-radius:12px">
          <div style="font-size:13px;color:var(--muted)">What members get</div>
          <ul style="margin:8px 0 0;padding-left:18px;color:var(--muted)">
            <li>Monthly guided session recordings</li>
            <li>Access to seasonal blend recipes</li>
            <li>Priority scheduling for 1:1</li>
          </ul>
          <div style="margin-top:10px"><a href="#plans" class="primary-cta">Join the circle</a></div>
        </div>
      </aside>
    </section>

    <section id="plans" class="reveal" data-reveal>
      <h2>Membership options</h2>
      <div class="plans">
        <div class="plan">
          <h3>Core Practice</h3>
          <div class="price">$19 / month</div>
          <div class="badge">Intro-friendly</div>
          <div class="features">Monthly guided audio • Seasonal blend sheet • 10% shop discount</div>
          <a href="{{PRIMARY_CTA_URL}}">Start Core</a>
        </div>
        <div class="plan">
          <h3>Ritual Circle</h3>
          <div class="price">$39 / month</div>
          <div class="badge">Most popular</div>
          <div class="features">Everything in Core + live group Q&A • priority booking</div>
          <a href="{{PRIMARY_CTA_URL}}">Join Circle</a>
        </div>
        <div class="plan">
          <h3>Seasonal Steward</h3>
          <div class="price">$129 / quarter</div>
          <div class="badge">Deep track</div>
          <div class="features">Quarterly 1:1 review • bespoke blend consult • exclusive drops</div>
          <a href="{{PRIMARY_CTA_URL}}">Apply</a>
        </div>
      </div>
    </section>

    <section class="faq reveal" data-reveal>
      <h4>Practical notes & safety</h4>
      <p>We prioritize safe, gradual scent practice. Members receive guidance on dilution, storage, and patch testing. Avoid direct skin application without proper dilution; perform a patch test and consult your health provider for pregnancy or medical concerns.</p>
      <p>Pets: some essential oils can affect animals. Keep blends out of reach and consult with a veterinarian for specific guidance.</p>
      <p>Refunds & cancellations: membership can be cancelled any time from your account page.</p>
    </section>

    <section class="reveal" data-reveal style="margin-top:20px">
      <h4>Still unsure?</h4>
      <p style="color:var(--muted)">Book a short orientation or try the practice above to experience the tone of our sessions.</p>
      <div style="margin-top:10px">
        <a class="btn" href="book.html">Reserve orientation</a>
        <button class="ghost" id="open-try-2" style="margin-left:8px">Try a guided moment</button>
      </div>
    </section>
  </main>

  <footer>
    <div class="wrap">Questions? Call {{PHONE}} • Email <a href="mailto:{{EMAIL}}">{{EMAIL}}</a></div>
  </footer>

  <!-- Try-it modal template -->
  <template id="try-template">
    <div class="modal-backdrop" role="dialog" aria-modal="true">
      <div class="modal" role="document" aria-labelledby="try-title">
        <h3 id="try-title">Guided: brief scent pause</h3>
        <p style="color:var(--muted)">A short sequence you can do seated — breathing, a short journaling prompt, and an intention to carry forward. No scents required; use it with or without a blend.</p>
        <div id="step-container">
          <div class="step" data-step>Step 1 — Settle (60s): find your seat and soften your gaze.</div>
          <div class="step" data-step>Step 2 — Breathe (60s): inhale for 4, exhale for 6. Repeat slowly.</div>
          <div class="step" data-step>Step 3 — Note (90s): write a single line about how you want to move through the next hour.</div>
          <div class="step" data-step>Step 4 — Anchor (30s): choose a short phrase to return to and breathe with it once.</div>
        </div>

        <div class="controls">
          <button class="btn" id="start-try">Begin</button>
          <button class="ghost" id="close-try">Close</button>
          <div style="margin-left:auto;color:var(--muted);font-size:13px">Accessible: Esc to close</div>
        </div>
      </div>
    </div>
  </template>

  <script>
    (function(){
      // Reveal on scroll with reduced-motion support
      const prefersReduced = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
      const reveals = document.querySelectorAll('[data-reveal]');
      if(prefersReduced) { reveals.forEach(r=>r.classList.add('visible')); }
      else{
        const io = new IntersectionObserver((entries)=>{
          entries.forEach(e=>{ if(e.isIntersecting){ e.target.classList.add('visible'); io.unobserve(e.target); } });
        },{threshold:0.08});
        reveals.forEach(r=>io.observe(r));
      }

      // Modal logic
      function openTry(){
        const tpl = document.getElementById('try-template');
        const node = tpl.content.cloneNode(true);
        const backdrop = node.querySelector('.modal-backdrop');
        document.body.appendChild(backdrop);
        const startBtn = backdrop.querySelector('#start-try');
        const closeBtn = backdrop.querySelector('#close-try');
        const steps = Array.from(backdrop.querySelectorAll('[data-step]'));
        let current = 0;
        let stepTimer = null;

        function showStep(idx){
          steps.forEach((s,i)=> s.style.display = i===idx? 'block':'none');
        }
        showStep(current);

        function beginSequence(){
          const durations = [60,60,90,30];
          showStep(current);
          stepTimer = setInterval(()=>{
            current += 1;
            if(current >= steps.length){
              cleanup();
              return;
            }
            showStep(current);
          }, durations[current]*1000);
          // immediate progress for first item to move through timed steps
          // Note: uses setInterval, not high-precision — intentionally simple.
        }

        function cleanup(){
          clearInterval(stepTimer);
          if(backdrop && backdrop.parentNode) backdrop.parentNode.removeChild(backdrop);
        }

        startBtn.addEventListener('click',()=>{
          startBtn.disabled = true;
          beginSequence();
        });
        closeBtn.addEventListener('click',cleanup);
        backdrop.addEventListener('click',(e)=>{ if(e.target === backdrop) cleanup(); });
        document.addEventListener('keydown',function esc(e){ if(e.key === 'Escape'){ cleanup(); document.removeEventListener('keydown',esc); } });
      }

      document.getElementById('open-try').addEventListener('click',openTry);
      document.getElementById('open-try-2').addEventListener('click',openTry);
    })();
  </script>
</body>
</html>"} 
