  <title>Our Path — {{BUSINESS_NAME}}</title>
  <style>
    :root{--bg:#fffaf6;--muted:#5f5f5f;--accent:#7aa884;--deep:#274235}
    body{margin:0;font-family:system-ui,-apple-system,Segoe UI,Roboto,Helvetica,Arial;background:var(--bg);color:var(--deep)}
