<body>
  <header>
    <div class="wrap nav">
      <div style="font-weight:700">{{BUSINESS_NAME}}</div>
      <nav>
        <a href="index.html">Welcome</a>
        <a href="services.html">Offerings</a>
        <a href="blends.html">Blends</a>
        <a href="shop.html">Shop</a>
        <a href="pricing.html">Membership</a>
        <a href="about.html" class="primary">Our Path</a>
        <a href="book.html">Reserve</a>
        <a href="contact.html">Reach</a>
      </nav>
    </div>
  </header>

  <main class="wrap">
    <section class="hero reveal" data-reveal>
      <h1>Practices that help you notice and choose</h1>
      <p class="meta">Clinical calm, clear direction — small scent-based rituals designed to fit into your day. Practices are framed to be supportive and mindful rather than prescriptive.</p>
    </section>

    <section class="story reveal" data-reveal>
      <div class="card">
        <h2>How we work</h2>
        <p class="meta">We craft short, repeatable practices and simple blends that may support attention, rest, or transition. Sessions emphasize safety, a gentle pace, and practical instructions for home use.</p>
        <div style="margin-top:12px">
          <h4>Foundational steps</h4>
          <ol style="color:var(--muted)">
            <li>Assess context and sensitivities</li>
            <li>Introduce low-dose scent options and dilution guidance</li>
            <li>Practice breathing and journaling prompts paired with scent</li>
          </ol>
        </div>
      </div>

      <aside class="card">
        <h4>Quick note</h4>
        <p class="meta">We avoid medical claims and use language like “may support.” Expect guidance about dilution, patch testing, and considerations for pregnancy and pets.</p>
        <div style="margin-top:10px"><button class="primary" id="open-try-about">Try a short pause</button></div>
      </aside>
    </section>

    <section class="framework reveal" data-reveal>
      <h3>Our framework</h3>
      <div class="pillar">
        <div style="width:10px;height:10px;border-radius:3px;background:var(--accent);margin-top:6px"></div>
        <div>
          <div class="pill-title">Assessment</div>
          <div style="color:var(--muted)">A brief intake to learn preferences and sensitivities before suggesting blends or rituals.</div>
        </div>
      </div>
      <div class="pillar">
        <div style="width:10px;height:10px;border-radius:3px;background:#b9d8c8;margin-top:6px"></div>
        <div>
          <div class="pill-title">Guidance</div>
          <div style="color:var(--muted)">Simple, repeatable steps that you can practice alone at home or in short group sessions.</div>
        </div>
      </div>
      <div class="pillar">
        <div style="width:10px;height:10px;border-radius:3px;background:#dfeee6;margin-top:6px"></div>
        <div>
          <div class="pill-title">Care</div>
          <div style="color:var(--muted)">Safety-forward instructions for dilution, patch testing, pregnancy guidance, and pets.</div>
        </div>
      </div>
    </section>

    <section class="reveal" data-reveal style="margin-top:18px">
      <h3>Meet the lead practitioner</h3>
      <div class="card">
        <p class="meta">A certified aromatherapy practitioner with a clinical, safety-forward approach. Sessions are small, attentive, and structured to help you integrate scent into daily routines in a way that may support steadiness.</p>
        <p style="margin-top:10px">Want to talk? <a href="book.html">Reserve a short orientation</a> or <a href="contact.html">email us</a>.</p>
      </div>
    </section>
  </main>

  <footer class="wrap footer">
    <div>Contact: {{PHONE}} • <a href="mailto:{{EMAIL}}">{{EMAIL}}</a></div>
  </footer>

  <script>
    (function(){
      const prefersReduced = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
      const reveals = document.querySelectorAll('[data-reveal]');
      if(prefersReduced){ reveals.forEach(r=>r.classList.add('visible')); }
      else{
        const io = new IntersectionObserver((entries)=>entries.forEach(e=>{ if(e.isIntersecting){ e.target.classList.add('visible'); io.unobserve(e.target); } }),{threshold:0.08});
        reveals.forEach(r=>io.observe(r));
      }

      // Reuse modal from other pages if included
      function openSimpleTry(){
        // Minimal guided exercise: inline prompt overlay
        const overlay = document.createElement('div');
        overlay.style.position='fixed';overlay.style.inset=0;overlay.style.display='flex';overlay.style.alignItems='center';overlay.style.justifyContent='center';overlay.style.background='rgba(10,10,8,0.36)';overlay.style.zIndex=120;
        overlay.innerHTML = '<div role="dialog" aria-modal="true" style="background:white;padding:18px;border-radius:12px;max-width:520px;box-shadow:0 20px 60px rgba(18,30,20,0.35)"><h3 style="margin-top:0">A short pause — 2 minutes</h3><p style="color:var(--muted)">Seated: inhale 4, exhale 6, repeat for one minute. Then write a single line about intention. Close when ready.</p><div style="margin-top:12px;display:flex;gap:8px"><button id="closeSimple" style="padding:8px 12px;border-radius:8px;background:#7aa884;color:white;border:0">Close</button></div></div>';
        document.body.appendChild(overlay);
        overlay.querySelector('#closeSimple').addEventListener('click',()=>overlay.remove());
        document.addEventListener('keydown',function esc(e){ if(e.key==='Escape'){ overlay.remove(); document.removeEventListener('keydown',esc); } });
      }

      document.getElementById('open-try-about').addEventListener('click',openSimpleTry);
    })();
  </script>
</body>
</html>"} 
{"path":"book.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8" />
  <meta name="viewport" content="width=device-width,initial-scale=1" />
  <title>Reserve — {{BUSINESS_NAME}}</title>
  <style>
    :root{--bg:#f6fbf8;--muted:#58635a;--accent:#4f8b64;--deep:#163c2d}
    body{margin:0;font-family:system-ui,-apple-system,Segoe UI,Roboto,Helvetica,Arial;background:var(--bg);color:var(--deep)}
    header{padding:12px 18px;border-bottom:1px solid rgba(22,60,45,0.06);background:white}
    .wrap{max-width:920px;margin:0 auto}
    nav a{margin-left:10px;text-decoration:none;color:var(--deep)}

    main{padding:24px}
    .hero{padding:18px;background:white;border-radius:12px;border:1px solid rgba(22,60,45,0.04)}
    h1{margin:0 0 6px}
    .steps{display:grid;gap:12px;margin-top:14px}
    .step{background:white;padding:12px;border-radius:10px;border:1px solid rgba(22,60,45,0.04)}
    .muted{color:var(--muted)}

    form{margin-top:18px;display:grid;gap:10px}
    input,select,textarea{padding:10px;border-radius:8px;border:1px solid rgba(22,60,45,0.08);font-size:15px}
    .actions{display:flex;gap:10px;align-items:center}
    .btn{background:var(--accent);color:white;padding:10px 12px;border-radius:8px;border:0}

    .policies{margin-top:12px;color:var(--muted);font-size:14px}

    .reveal{opacity:0;transform:translateY(12px);transition:opacity 480ms ease,transform 480ms ease}
    .reveal.visible{opacity:1;transform:none}
    @media (prefers-reduced-motion:reduce){.reveal{transition:none;opacity:1;transform:none}}
  </style>
</head>
<body>
  <header>
    <div class="wrap" style="display:flex;align-items:center;justify-content:space-between">
      <div style="font-weight:700">{{BUSINESS_NAME}}</div>
      <nav>
        <a href="index.html">Welcome</a>
        <a href="services.html">Offerings</a>
        <a href="pricing.html">Membership</a>
        <a href="about.html">Our Path</a>
        <a href="contact.html">Reach</a>
      </nav>
    </div>
  </header>

  <main class="wrap">
    <section class="hero reveal" data-reveal>
      <h1>Reserve a short orientation</h1>
      <p class="muted">A 20-minute session to review preferences, sensitivities, and a safe introduction to simple blends and practices. Sessions are private and safety-first.</p>
    </section>

    <section class="steps reveal" data-reveal>
      <div class="step">
        <strong>Step 1</strong> — Choose a slot. If you are pregnant or have significant health concerns, select the "safety consult" option and note that on the form.
      </div>
      <div class="step">
        <strong>Step 2</strong> — Fill the intake below. We will ask about allergies, pets in the home, and any medication that may be relevant to scent sensitivity.
      </div>
      <div class="step">
        <strong>Step 3</strong> — Bring a notepad. The session includes practical dilution notes and a short at-home practice you can repeat.
      </div>
    </section>

    <form class="reveal" data-reveal aria-label="Booking form" onsubmit="event.preventDefault();handleBooking(this)">
      <input name="name" placeholder="Full name" required />
      <input name="email" type="email" placeholder="Email" required />
      <input name="phone" placeholder="Phone (optional)" />
      <select name="type" required>
        <option value="orientation">20-minute orientation</option>
        <option value="safety">Safety consult (pregnancy/pets)</option>
        <option value="member">Member check-in (existing)</option>
      </select>
      <textarea name="notes" rows="4" placeholder="Any allergies, sensitivities, or questions"></textarea>
      <div class="actions">
        <button class="btn" type="submit">Request a reservation</button>
        <button type="button" class="btn" style="background:#88bfa1" id="try-book">Try a moment</button>
      </div>
      <div class="policies">
        By requesting a reservation you agree to our safety-first approach. If pregnant or nursing, please book a safety consult. We provide dilution & patch test instructions before any topical recommendations.
      </div>
    </form>

    <section class="reveal" data-reveal style="margin-top:18px">
      <h3>FAQ — Safety highlights</h3>
      <p class="muted">Patch test: dilute recommended blends and apply a small amount on the inner forearm; wait 24 hours to check for irritation. Pets: certain oils affect animals; we provide pet-safe alternatives. Pregnancy: avoid certain oil types; we will always recommend a pregnancy-safe plan when asked.</p>
    </section>
  </main>

  <script>
    (function(){
      const prefersReduced = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
      const reveals = document.querySelectorAll('[data-reveal]');
      if(prefersReduced){ reveals.forEach(r=>r.classList.add('visible')); }
